"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["99244"],{11190(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.calendario_dias_uteis_congelado.dia_duplicado","status":422,"titulo":"O calend\xe1rio congelado traz o mesmo dia n\xe3o \xfatil mais de uma vez"},"descricao":{"codigo":"uniplus.selecao.calendario_dias_uteis_congelado.dia_duplicado","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["O calend\xe1rio de dias \xfateis vigente traz o mesmo dia n\xe3o \xfatil mais de uma vez, com a mesma\\nabrang\xeancia e o mesmo recorte territorial (munic\xedpio e UF). A mensagem informa a data repetida.","O mesmo dia pode aparecer mais de uma vez quando a abrang\xeancia ou o recorte s\xe3o diferentes: um\\nferiado nacional que tamb\xe9m \xe9 municipal s\xe3o dois fatos, com fundamentos distintos. O que se recusa \xe9\\no registro igual a outro em data, abrang\xeancia, munic\xedpio e UF. Dois registros iguais indicam\\ncadastro inconsistente, e absorv\xea-los na c\xf3pia esconderia o defeito dentro de uma vers\xe3o\\nimut\xe1vel.","O calend\xe1rio de dias \xfateis vigente \xe9 cadastrado no m\xf3dulo Configura\xe7\xe3o, e a vers\xe3o do processo\\ncongela uma c\xf3pia dele por valor, com a lista dos dias n\xe3o \xfateis (UNI-REQ-0080). Ao copi\xe1-lo, o\\nsistema confere de novo cada dia e o conjunto, e recusa o que o cadastro n\xe3o aceitaria. A recusa\\ns\xf3 vale para o processo que depende do calend\xe1rio, isto \xe9, o que tem prazo de recurso (ver\\n[calend\xe1rio vigente ausente](/erros/uniplus.selecao.processo_seletivo.calendario_vigente_ausente)); um processo sem contagem sobre dia \xfatil segue normalmente, porque n\xe3o usa o dado.","A confer\xeancia vem depois das da localidade ([`localidade_ausente`](/erros/uniplus.selecao.processo_seletivo.localidade_ausente)) e da conven\xe7\xe3o de contagem\\n([`algoritmo_contagem_prazo_nao_declarado`](/erros/uniplus.selecao.processo_seletivo.algoritmo_contagem_prazo_nao_declarado)), e antes das demais confer\xeancias de conformidade e do cronograma. A consulta de\\nconformidade do processo mostra o item \\"Calend\xe1rio de dias \xfateis vigente\\" como pendente enquanto o\\ncalend\xe1rio vigente estiver nessa condi\xe7\xe3o. Nada \xe9 gravado.","Esta \xe9 a \xfaltima confer\xeancia da c\xf3pia, depois das do identificador e da vers\xe3o do calend\xe1rio, e\\nde a lista n\xe3o estar vazia ([`sem_dia_nao_util`](/erros/uniplus.selecao.calendario_dias_uteis_congelado.sem_dia_nao_util))."],"comoResolver":["A causa n\xe3o est\xe1 na configura\xe7\xe3o do processo, e nada nela corrige a recusa: o dado vem do\\ncalend\xe1rio de dias \xfateis vigente, cadastrado no m\xf3dulo Configura\xe7\xe3o. Como a vers\xe3o publicada\\ncongela o calend\xe1rio por valor, a corre\xe7\xe3o \xe9 na origem, antes de publicar ou retificar:\\ncadastre um calend\xe1rio corrigido, que o cadastro confere ao criar, coloque-o em vig\xeancia\\ne repita a opera\xe7\xe3o.","O cadastro recusa a repeti\xe7\xe3o ao criar o calend\xe1rio ([`data_duplicada_no_calendario`](/erros/uniplus.configuracao.calendario_dias_uteis.data_duplicada_no_calendario)).\\nUm calend\xe1rio vigente nessa condi\xe7\xe3o indica dado gravado por caminho que n\xe3o passou por essa\\nconfer\xeancia, e a causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Calendario dias uteis congelado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);